174	
175		// Start config file watcher in background
176		ctx, cancel := context.WithCancel(context.Background())
177		defer cancel()
178		go s.watchConfigAndReload(ctx)
179	
180		// Wait for interrupt signal to gracefully shut down the server
181		signalChan := make(chan os.Signal, 1)
182		signal.Notify(signalChan, syscall.SIGINT, syscall.SIGTERM)
