248	func (s *Server) reloadRouterFromConfig(
249		source string,
250		configPath string,
251		candidateCfg *config.RouterConfig,
252	) error {
253		if source == "file" {
254			if err := ensureReloadConfigModels(candidateCfg); err != nil {
255				return fmt.Errorf("model download preflight failed: %w", err)
256			}
257		}
258	
259		runtimeState, err := prepareReloadRuntime(candidateCfg)
260		if err != nil {
261			return fmt.Errorf("runtime dependency init failed: %w", err)
262		}
263	
264		newRouter, err := buildReloadRouter(candidateCfg)
265		if err != nil {
266			return err
267		}
268		attachRuntimeRegistry(newRouter, s.runtime)
269		if err := warmupReloadRouter(newRouter, runtimeState); err != nil {
270			_ = newRouter.Close()
271			return fmt.Errorf("runtime warmup failed: %w", err)
272		}
273	
274		// Kubernetes updates are already published through config.Replace in the
275		// controller callback. Replacing again here would re-enqueue the same config
276		// update and can cause duplicate reload notifications.
277		if source != "kubernetes" && s.runtime == nil {
278			replaceReloadConfig(candidateCfg)
279		}
280		logLoadedRouterConfig(configPath, candidateCfg)
281		oldRouter := s.service.GetRouter()
282		s.service.Swap(newRouter)
283		if oldRouter != nil {
284			_ = oldRouter.Close()
285		}
286		publishRouterState(candidateCfg, newRouter, s.runtime)
287		return nil
288	}
