298	func resolveServerConfig(s *Server) *config.RouterConfig {
299		if s != nil && s.service != nil {
300			if router := s.service.GetRouter(); router != nil && router.Config != nil {
301				return router.Config
302			}
303		}
304		if s != nil && s.runtime != nil {
305			return s.runtime.CurrentConfig()
306		}
307		return config.Get()
308	}
309	
310	func (s *Server) usesKubernetesConfigSource() bool {
311		cfg := resolveServerConfig(s)
312		return cfg != nil && cfg.ConfigSource == config.ConfigSourceKubernetes
313	}
