315	func logReloadRuntimeLifecycleEvent(event modelruntime.Event) {
316		if event.Status != modelruntime.TaskFailed && event.Status != modelruntime.TaskSkipped {
317			return
318		}
319	
320		payload := map[string]interface{}{
321			"task":        event.Task,
322			"best_effort": event.BestEffort,
323		}
324		if event.Error != nil {
325			payload["error"] = event.Error.Error()
326		}
327		if event.Status == modelruntime.TaskSkipped {
328			logging.ComponentWarnEvent("extproc", "runtime_lifecycle_task_skipped", payload)
329			return
330		}
331		if event.BestEffort {
332			logging.ComponentWarnEvent("extproc", "runtime_lifecycle_task_failed", payload)
333			return
334		}
335		logging.ComponentErrorEvent("extproc", "runtime_lifecycle_task_failed", payload)
336	}
337	
338	func attachRuntimeRegistry(router *OpenAIRouter, runtimeRegistry *routerruntime.Registry) {
339		if router == nil {
340			return
341		}
342		router.RuntimeRegistry = runtimeRegistry
343	}
344	
345	func publishRouterState(
346		cfg *config.RouterConfig,
347		router *OpenAIRouter,
348		runtimeRegistry *routerruntime.Registry,
349	) {
350		if router == nil {
351			return
352		}
353		if runtimeRegistry != nil {
354			runtimeRegistry.PublishRouterRuntime(cfg, router.ClassificationService, router.MemoryStore)
355			runtimeRegistry.SetModelSelector(router.ModelSelector)
356			runtimeRegistry.SetLearningRuntime(router.routerLearningRuntimeState())
357			return
358		}
359		services.SetGlobalClassificationService(router.ClassificationService)
360		memory.SetGlobalMemoryStore(router.MemoryStore)
361	}
