19	// handleRequestBodyDispatch routes body messages to the correct handler.
20	//
21	// BUFFERED mode (default): the message goes straight to handleRequestBody.
22	//
23	// STREAMED mode (streamed_body_mode: true in config): Envoy sends multiple
24	// body messages. A StreamedBodyHandler accumulates chunks, detects the model
25	// from the first few KB, and either passes through or accumulates for the
26	// full pipeline on end_of_stream.
27	func (r *OpenAIRouter) handleRequestBodyDispatch(v *ext_proc.ProcessingRequest_RequestBody, ctx *RequestContext) (*ext_proc.ProcessingResponse, error) {
28		// Honor x-vsr-skip-processing before allocating a streamed-body handler.
29		// This guarantees no chunk accumulation, model detection, or buffered
30		// pipeline runs for opted-out requests, regardless of streamed_body_mode.
31		if ctx.SkipProcessing {
32			if ctx.FullDuplexRequestBody {
33				return newFullDuplexRequestBodyResponse(v.RequestBody.GetBody(), v.RequestBody.GetEndOfStream()), nil
34			}
35			return newContinueRequestBodyResponse(), nil
36		}
37	
38		eos := v.RequestBody.GetEndOfStream()
39	
40		// If we already have a handler from a previous chunk, continue streaming
41		if ctx.StreamedBody != nil {
42			resp, err := ctx.StreamedBody.HandleChunk(v.RequestBody, ctx)
43			if eos {
44				ctx.StreamedBody.Release()
45				ctx.StreamedBody = nil
46			}
47			return resp, err
48		}
49	
50		// Decide mode based on config: only use streaming handler when explicitly enabled
51		streamedMode := r.Config != nil && r.Config.StreamedBodyMode
52		if ctx.FullDuplexRequestBody && !streamedMode {
53			return newFullDuplexRequestBodyResponse(v.RequestBody.GetBody(), eos), nil
54		}
55		if streamedMode && (!eos || ctx.FullDuplexRequestBody) {
56			ctx.StreamedBody = newStreamedBodyHandler(r, ctx)
57			resp, err := ctx.StreamedBody.HandleChunk(v.RequestBody, ctx)
58			if eos {
59				ctx.StreamedBody.Release()
60				ctx.StreamedBody = nil
61			}
62			return resp, err
63		}
64	
65		// BUFFERED mode or single-message STREAMED — use classic pipeline
66		return r.handleRequestBody(v, ctx)
67	}
68	
69	// Process implements the ext_proc calls
70	func (r *OpenAIRouter) Process(stream ext_proc.ExternalProcessor_ProcessServer) (retErr error) {
71		logging.Debugf("Processing at stage [init]")
72	
73		// Recover from any panic (including OOM kills surfaced as runtime panics from
74		// CGO inference calls) so a single bad request cannot take down the gRPC server.
75		defer func() {
76			if rec := recover(); rec != nil {
77				logging.Errorf("Process: recovered panic: %v\n%s", rec, debug.Stack())
78				retErr = status.Errorf(codes.Internal, "internal error: %v", rec)
79			}
80		}()
81	
82		// Initialize request context
83		ctx := &RequestContext{
84			Headers:      make(map[string]string),
85			TraceContext: stream.Context(),
86		}
87	
88		for {
89			req, err := stream.Recv()
90			if err != nil {
91				return r.handleProcessReceiveError(ctx, err)
92			}
93	
94			if err := r.handleProcessRequest(stream, req, ctx); err != nil {
95				return err
96			}
97		}
98	}
99	
100	func (r *OpenAIRouter) handleProcessReceiveError(ctx *RequestContext, err error) error {
101		if ctx.IsStreamingResponse && !ctx.StreamingComplete {
102			ctx.StreamingAborted = true
103			logging.Debugf("Streaming response aborted before completion, will not cache")
104		}
105		if ctx.InflightToken != 0 {
106			inflight.End(ctx.RequestModel, ctx.InflightToken)
107			ctx.InflightToken = 0
108		}
109	
110		if errors.Is(err, io.EOF) {
111			logging.Debugf("Stream ended gracefully")
112			return nil
113		}
114	
115		if handled := handleProcessStatusError(ctx, err); handled {
116			return nil
117		}
118	
119		if handled := handleProcessContextError(ctx, err); handled {
120			return nil
121		}
122	
123		logging.Errorf("Error receiving request: %v", err)
124		return err
125	}
126	
127	func handleProcessStatusError(ctx *RequestContext, err error) bool {
128		s, ok := status.FromError(err)
129		if !ok {
130			return false
131		}
132	
133		switch s.Code() {
134		case codes.Canceled:
135			return true
136		case codes.DeadlineExceeded:
137			recordProcessTimeout(ctx)
138			return true
139		default:
140			return false
141		}
142	}
143	
144	func handleProcessContextError(ctx *RequestContext, err error) bool {
145		if errors.Is(err, context.Canceled) {
146			logging.Debugf("Stream canceled gracefully")
147			return true
148		}
149		if errors.Is(err, context.DeadlineExceeded) {
150			recordProcessTimeout(ctx)
151			return true
152		}
153		return false
154	}
155	
156	func recordProcessTimeout(ctx *RequestContext) {
157		logging.Infof("Stream deadline exceeded")
158		metrics.RecordRequestError(ctx.RequestModel, "timeout")
159	}
160	
161	func (r *OpenAIRouter) handleProcessRequest(
162		stream ext_proc.ExternalProcessor_ProcessServer,
163		req *ext_proc.ProcessingRequest,
164		ctx *RequestContext,
165	) error {
166		if protocolConfig := req.GetProtocolConfig(); protocolConfig != nil {
167			ctx.FullDuplexRequestBody = protocolConfig.GetRequestBodyMode() == http_ext.ProcessingMode_FULL_DUPLEX_STREAMED
168		}
169	
170		switch v := req.Request.(type) {
171		case *ext_proc.ProcessingRequest_RequestHeaders:
172			return r.processRequestHeaders(stream, v, ctx)
173		case *ext_proc.ProcessingRequest_RequestBody:
174			return r.processRequestBody(stream, v, ctx)
175		case *ext_proc.ProcessingRequest_ResponseHeaders:
176			return r.processResponseHeaders(stream, v, ctx)
177		case *ext_proc.ProcessingRequest_ResponseBody:
178			return r.processResponseBody(stream, v, ctx)
179		default:
180			return processUnknownRequest(stream, v)
181		}
182	}
183	
184	func (r *OpenAIRouter) processRequestHeaders(
185		stream ext_proc.ExternalProcessor_ProcessServer,
186		v *ext_proc.ProcessingRequest_RequestHeaders,
187		ctx *RequestContext,
188	) error {
189		response, err := r.handleRequestHeaders(v, ctx)
190		if err != nil {
191			logging.Errorf("handleRequestHeaders failed: %v", err)
192			return err
193		}
194		if err := sendResponse(stream, response, "request header"); err != nil {
195			logging.Errorf("sendResponse for headers failed: %v", err)
196			return err
197		}
198		return nil
199	}
200	
201	func (r *OpenAIRouter) processRequestBody(
202		stream ext_proc.ExternalProcessor_ProcessServer,
203		v *ext_proc.ProcessingRequest_RequestBody,
204		ctx *RequestContext,
205	) error {
206		response, err := r.handleRequestBodyDispatch(v, ctx)
207		if err != nil {
208			logging.Errorf("handleRequestBody failed: %v", err)
209			return err
210		}
211		// FULL_DUPLEX_STREAMED explicitly permits the processor to buffer any
212		// number of input chunks before sending a StreamedBodyResponse. A nil
213		// response here means this chunk was retained for the eventual EOS reply.
214		if response == nil && ctx.FullDuplexRequestBody {
215			return nil
216		}
217		if err := sendResponse(stream, response, "request body"); err != nil {
218			logging.Errorf("sendResponse for body failed: %v", err)
219			return err
220		}
221		return nil
222	}
223	
224	func (r *OpenAIRouter) processResponseHeaders(
225		stream ext_proc.ExternalProcessor_ProcessServer,
226		v *ext_proc.ProcessingRequest_ResponseHeaders,
227		ctx *RequestContext,
228	) error {
229		response, err := r.handleResponseHeaders(v, ctx)
230		if err != nil {
231			return err
232		}
233		return sendResponse(stream, response, "response header")
234	}
235	
236	func (r *OpenAIRouter) processResponseBody(
237		stream ext_proc.ExternalProcessor_ProcessServer,
238		v *ext_proc.ProcessingRequest_ResponseBody,
239		ctx *RequestContext,
240	) error {
241		response, err := r.handleResponseBody(v, ctx)
242		if err != nil {
243			return err
244		}
245		return sendResponse(stream, response, "response body")
246	}
247	
248	func processUnknownRequest(
249		stream ext_proc.ExternalProcessor_ProcessServer,
250		request interface{},
251	) error {
252		logging.Warnf("Unknown request type: %v", request)
253	
254		response := &ext_proc.ProcessingResponse{
255			Response: &ext_proc.ProcessingResponse_RequestBody{
256				RequestBody: &ext_proc.BodyResponse{
257					Response: &ext_proc.CommonResponse{
258						Status: ext_proc.CommonResponse_CONTINUE,
259					},
260				},
261			},
262		}
263	
264		return sendResponse(stream, response, "unknown")
265	}
