13		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
14		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/headers"
15		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/ir"
16		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
17		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/tracing"
18	)
19	
20	// handleRequestHeaders processes the request headers.
21	func (r *OpenAIRouter) handleRequestHeaders(v *ext_proc.ProcessingRequest_RequestHeaders, ctx *RequestContext) (*ext_proc.ProcessingResponse, error) {
22		ctx.StartTime = time.Now()
23	
24		span := startRequestHeaderSpan(v, ctx)
25		defer span.End()
26	
27		method, path := captureRequestHeaders(v, ctx, r.skipProcessingEnabled())
28	
29		setRequestHeaderSpanAttributes(span, ctx, method, path)
30		detectClientProtocol(path, ctx)
31		applyHeaderPassThroughPolicy(ctx)
32	
33		// Honor x-vsr-skip-processing as early as possible: once captured we bypass
34		// every router-side header check (replay API, validation, response-API
35		// translation) and emit a plain CONTINUE so the request flows through.
36		// Streaming detection still runs because the same flag drives mode selection
37		// for downstream filters and is cheap; the body and response handlers will
38		// also short-circuit in the no-op path.
39		if ctx.SkipProcessing {
40			detectStreamingExpectation(ctx)
41			return newContinueRequestHeadersResponse(), nil
42		}
43	
44		if replayResp := r.handleRouterReplayAPI(method, path); replayResp != nil {
45			return replayResp, nil
46		}
47	
48		detectStreamingExpectation(ctx)
49		if modelsResp, err := r.handleModelsRequestHeaders(method, path); err != nil || modelsResp != nil {
50			return modelsResp, err
51		}
52		if responseAPIResp, err := r.handleResponseAPIRequestHeaders(method, path, ctx); err != nil || responseAPIResp != nil {
