15	// sendResponse sends a response with proper error handling and logging.
16	// If response is nil, a CONTINUE BodyResponse is sent as a safe fallback
17	// to prevent nil pointer dereferences in Envoy or test assertions.
18	func sendResponse(stream ext_proc.ExternalProcessor_ProcessServer, response *ext_proc.ProcessingResponse, msgType string) error {
19		if response == nil {
20			logging.Warnf("Nil response for %s stage — sending CONTINUE fallback to avoid nil dereference", msgType)
21			response = &ext_proc.ProcessingResponse{
22				Response: &ext_proc.ProcessingResponse_RequestBody{
23					RequestBody: &ext_proc.BodyResponse{
24						Response: &ext_proc.CommonResponse{
25							Status: ext_proc.CommonResponse_CONTINUE,
26						},
27					},
28				},
29			}
30		}
31	
32		// Redact credentials (Authorization / x-api-key / ...) before dumping the
33		// mutation: the credential resolver injects the upstream provider key as a
34		// set-header, so a verbatim %+v would leak it to the log (CWE-532). Gate on
35		// the debug level so the clone+redact cost is paid only when it is logged.
36		if logging.DebugEnabled() {
37			logging.Debugf("Processing at stage [%s]: %+v", msgType, redactResponseForLog(response))
38		}
39	
40		if err := stream.Send(response); err != nil {
41			logging.Errorf("Error sending %s response: %v", msgType, err)
42			return err
43		}
44		return nil
45	}
46	
47	// parseOpenAIRequest parses the raw JSON using the OpenAI SDK types
48	func parseOpenAIRequest(data []byte) (*openai.ChatCompletionNewParams, error) {
49		var req openai.ChatCompletionNewParams
50		if err := json.Unmarshal(data, &req); err != nil {
51			return nil, err
52		}
53		return &req, nil
54	}
