56	// extractStreamParam extracts the stream parameter from the original request body.
57	// Uses gjson for O(scan) extraction without allocating a map.
58	func extractStreamParam(originalBody []byte) bool {
59		return extractStreamParamFast(originalBody)
60	}
61	
62	// serializeOpenAIRequestWithStream converts request back to JSON, preserving
63	// the stream parameter from the original request. Uses sjson for in-place
64	// field insertion instead of unmarshal → modify → marshal.
65	func serializeOpenAIRequestWithStream(req *openai.ChatCompletionNewParams, hasStreamParam bool) ([]byte, error) {
66		sdkBytes, err := json.Marshal(req)
67		if err != nil {
68			return nil, err
69		}
70		if hasStreamParam {
71			sdkBytes = addStreamFieldsFast(sdkBytes)
72		}
73		return sdkBytes, nil
74	}
